<script setup lang="ts">
import { ref, watch } from 'vue'
import FormDateInput from '../../../../../shared/components/form/FormDateInput.vue'
import FormField from '../../../../../shared/components/form/FormField.vue'
import FormInput from '../../../../../shared/components/form/FormInput.vue'
import FormSelect from '../../../../../shared/components/form/FormSelect.vue'
import FormTextarea from '../../../../../shared/components/form/FormTextarea.vue'
import type { LoanPayload, RepaymentPayload, TeamLoan, TeamMember } from '../../types/teamLoan'
const props = defineProps<{ mode: 'create' | 'repay' | 'void'; members: TeamMember[]; loan: TeamLoan | null; submitting: boolean; error: string }>()
const emit = defineEmits<{ submitLoan: [LoanPayload]; submitRepayment: [RepaymentPayload]; voidLoan: [string] }>()
const now = new Date(); const today = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`
const loan = ref({ borrower_id: '', amount: '', issued_at: today, due_at: null as string | null, purpose: '', method: 'bank_transfer' as LoanPayload['method'], reference: null as string | null, notes: null as string | null, borrower: { id: '', name: '', username: null as string | null }, remaining_amount: '0', code: '' })
const repayment = ref<RepaymentPayload>({ amount: '', repaid_at: today, method: 'bank_transfer', reference: null, notes: null })
const reason = ref(''); const methods = [{ value: 'bank_transfer', label: 'Transfer bank' }, { value: 'cash', label: 'Tunai' }, { value: 'other', label: 'Lainnya' }]
watch(() => props.loan, (selected) => { repayment.value.amount = ''; reason.value = ''; loan.value.borrower = selected?.borrower ?? { id: '', name: '', username: null }; loan.value.remaining_amount = selected?.remaining_amount ?? '0'; loan.value.code = selected?.code ?? '' }, { immediate: true })
function submit() { if (props.mode === 'create') emit('submitLoan', { borrower_id: loan.value.borrower_id, amount: loan.value.amount, issued_at: loan.value.issued_at, due_at: loan.value.due_at, purpose: loan.value.purpose.trim(), method: loan.value.method, reference: loan.value.reference?.trim() || null, notes: loan.value.notes?.trim() || null }); else if (props.mode === 'repay') emit('submitRepayment', { ...repayment.value, reference: repayment.value.reference?.trim() || null, notes: repayment.value.notes?.trim() || null }); else emit('voidLoan', reason.value.trim()) }
</script>
<template><form class="form" @submit.prevent="submit"><div v-if="error" class="error" role="alert">{{ error }}</div>
<template v-if="mode === 'create'"><div class="grid"><FormField id="loan-user" label="Anggota tim" required><FormSelect id="loan-user" v-model="loan.borrower_id" :options="members.map(m => ({ value: m.id, label: `${m.name}${m.username ? ` (@${m.username})` : ''}` }))" placeholder="Pilih anggota" /></FormField><FormField id="loan-amount" label="Nominal kasbon (Rp)" required><FormInput id="loan-amount" v-model="loan.amount" type="number" min="0.01" step="0.01" required inputmode="decimal" placeholder="Contoh: 250000" /></FormField><FormField id="loan-date" label="Tanggal kasbon" required><FormDateInput id="loan-date" v-model="loan.issued_at" required /></FormField><FormField id="loan-due" label="Target pelunasan"><FormDateInput id="loan-due" v-model="loan.due_at" /></FormField><FormField id="loan-method" label="Metode penyerahan" required><FormSelect id="loan-method" v-model="loan.method" :options="methods" /></FormField><FormField id="loan-ref" label="Referensi"><FormInput id="loan-ref" v-model="loan.reference" maxlength="100" /></FormField><FormField id="loan-purpose" label="Keperluan" full required><FormInput id="loan-purpose" v-model="loan.purpose" maxlength="180" required /></FormField><FormField id="loan-notes" label="Catatan" full><FormTextarea id="loan-notes" v-model="loan.notes" rows="3" /></FormField></div><p class="hint">Kasbon mengurangi saldo kas tersedia dan tercatat sebagai piutang, bukan biaya project.</p></template>
<template v-else-if="mode === 'repay'"><p class="context">{{ loan?.borrower.name }} · Sisa <strong>Rp {{ Number(loan?.remaining_amount || 0).toLocaleString('id-ID') }}</strong></p><div class="grid"><FormField id="repay-amount" label="Nominal cicilan (Rp)" required><FormInput id="repay-amount" v-model="repayment.amount" type="number" min="0.01" :max="loan?.remaining_amount" step="0.01" required inputmode="decimal" /></FormField><FormField id="repay-date" label="Tanggal pembayaran" required><FormDateInput id="repay-date" v-model="repayment.repaid_at" required /></FormField><FormField id="repay-method" label="Metode" required><FormSelect id="repay-method" v-model="repayment.method" :options="methods" /></FormField><FormField id="repay-ref" label="Referensi"><FormInput id="repay-ref" v-model="repayment.reference" maxlength="100" /></FormField><FormField id="repay-notes" label="Catatan" full><FormTextarea id="repay-notes" v-model="repayment.notes" rows="3" /></FormField></div></template>
<template v-else><p class="context">{{ loan?.code }} · {{ loan?.borrower.name }}</p><FormField id="loan-reason" label="Alasan koreksi" required><FormTextarea id="loan-reason" v-model="reason" rows="3" minlength="5" maxlength="500" required /></FormField></template>
<div class="actions"><button type="submit" :disabled="submitting">{{ submitting ? 'Menyimpan...' : mode === 'create' ? 'Simpan kasbon' : mode === 'repay' ? 'Simpan pembayaran' : 'Koreksi kasbon' }}</button></div></form></template>
<style scoped>.form{padding:20px 24px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.hint,.context{padding:11px 12px;border:1px solid #ffffff12;border-radius:8px;color:#aab09f;font-size:11px;line-height:1.5}.context strong{color:#f0d56a}.error{margin-bottom:14px;padding:10px 12px;border-radius:8px;background:#a7463c20;color:#ffb4a8;font-size:11px}.actions{display:flex;justify-content:flex-end;margin-top:18px;padding-top:14px;border-top:1px solid #ffffff12}.actions button{min-height:39px;padding:0 15px;border:0;border-radius:8px;background:#ffd64c;color:#263215;font-weight:700}.actions button:disabled{opacity:.55}@media(max-width:520px){.form{padding:17px}.grid{grid-template-columns:1fr}.actions{position:sticky;bottom:0;background:#20221f;padding-bottom:calc(8px + env(safe-area-inset-bottom))}}</style>
